// Add uploads a file and optionally associates it with a deal, person,
// organization, product, activity, lead or project.
//
// The multipart/form-data body is built internally and buffered, so the
// request is replayable and retried on 429 and 5xx like every other call.
func (s *FilesService) Add(ctx context.Context, fileName string, content io.Reader, opts ...FilesOption) (*File, error) {
	if fileName == "" {
		return nil, fmt.Errorf("file name is required")
	}
	if content == nil {
		return nil, fmt.Errorf("file content is required")
	}
	cfg := newFilesOptions(opts)

	fields := url.Values{}
	if cfg.dealID != nil {
		fields.Set("deal_id", strconv.FormatInt(int64(*cfg.dealID), 10))
	}
	if cfg.personID != nil {
		fields.Set("person_id", strconv.FormatInt(int64(*cfg.personID), 10))
	}
	if cfg.orgID != nil {
		fields.Set("org_id", strconv.FormatInt(int64(*cfg.orgID), 10))
	}
	if cfg.productID != nil {
		fields.Set("product_id", strconv.FormatInt(int64(*cfg.productID), 10))
	}
	if cfg.activityID != nil {
		fields.Set("activity_id", strconv.FormatInt(int64(*cfg.activityID), 10))
	}
	if cfg.leadID != nil {
		fields.Set("lead_id", string(*cfg.leadID))
	}
	if cfg.projectID != nil {
		fields.Set("project_id", strconv.FormatInt(int64(*cfg.projectID), 10))
	}

	contentType, body, err := multipartbody.NewFile("file", fileName, content, fields)
	if err != nil {
		return nil, err
	}

	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", contentType))

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, "/files", cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file data in response")
	}
	return payload.Data, nil
}

